INSERT INTO public.refunds(prepayment_id,order_id,out_refund_no,idempotency_key_hash,amount_cents,currency,reason_code,requested_by_user_id,requested_by_account_id,provider_request_json,provider_request_digest,provider_state,create_attempted_at,provider_refund_id,materialization_state,pending_reason_code,materialized_at,lease_kind,lease_owner,lease_expires_at,record_version,next_query_at,created_at,updated_at) VALUES(payment_id,order_id,convert_to(out_no,'UTF8'),key_bytes,p.expected_amount_cents,p.currency,reason,CASE WHEN merchant THEN NULL ELSE p_actor END,CASE WHEN merchant THEN a.id ELSE NULL END,request_json::jsonb,sha256(convert_to(request_json,'UTF8')),'READY',NULL,NULL,'AWAITING_PROVIDER',NULL,NULL,NULL,NULL,NULL,1,NULL,now_at,now_at) RETURNING * INTO r;IF r.id=0 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
UPDATE public.orders SET state='REFUNDING',refunding_at=now_at,redemption_token_ciphertext=NULL,redemption_key_version=NULL,record_version=record_version+1,updated_at=now_at WHERE id=order_id AND record_version>0;GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
provider_text:='';receipt:=jsonb_build_object('ID',r.id,'PrepaymentID',r.prepayment_id,'OrderID',coalesce(r.order_id,0),'State',r.provider_state,'MaterializationState',r.materialization_state,'AmountCents',r.amount_cents,'Currency',r.currency,'RequestedAt',p_now->>'canonical','ProviderRefundID',provider_text,'PendingReason',coalesce(r.pending_reason_code,''));IF length(substring(p_now->>'canonical' FROM '^([0-9]+)-')) IS DISTINCT FROM 4 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
