IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
RAISE;
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_request_paid_v2(p_actor numeric,p_prepayment numeric,p_reason_hex text,p_key_hash text,p_request_hash text,p_now jsonb,p_notify_url_hex text,p_environment text)
