payment_id:=p_prepayment;order_id:=NULL;SELECT id,role,auth_version INTO a.id,a.role,a.auth_version FROM public.merchant_accounts WHERE bound_user_id=p_actor AND enabled=true AND deleted_at IS NULL AND role='OWNER' FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','FORBIDDEN');END IF;IF a.id IS NULL OR a.auth_version IS NULL OR a.id NOT BETWEEN 0 AND 18446744073709551615 OR a.auth_version NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
