IF p.provider_state<>'PAID' OR p.materialization_state<>'PENDING_MANUAL' THEN RETURN jsonb_build_object('outcome','TRANSITION_NOT_ALLOWED');END IF;before_state:='PENDING_MANUAL';
-- Validate immutable parent and exact reviewed ownership in the original new-intent transaction, after replay and before RNG.
