parent_provider:=coalesce(parent_provider,'');
parent_entry:=jsonb_build_object('ordinal','1','kind','PAYMENT','appid_hex',encode(p.expected_appid,'hex'),'mchid_hex',encode(p.expected_mchid,'hex'),'out_trade_no_hex',encode(p.out_trade_no,'hex'),'out_refund_no_hex','','provider_id_hex',parent_provider,'payment_provider_id_hex',parent_provider);
parent_fact:=public.order_billing_ownership_facts_v1(p_environment,jsonb_build_array(parent_entry),0);
IF parent_fact->>'outcome' IS DISTINCT FROM 'FOUND' OR parent_fact->'entries'->0->'payment_proof'->>'state' IS DISTINCT FROM 'VALID' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
parent_fact:=parent_fact->'entries'->0;parent_envs:='{}';parent_leaves:='{}';parent_seen:=ARRAY[]::text[];
IF convert_from(p.out_trade_no,'UTF8') ~ '^OU1P[0-9a-f]{28}$' THEN parent_envs:=parent_envs||jsonb_build_object('uat',true);ELSIF convert_from(p.out_trade_no,'UTF8') ~ '^OP1P[0-9a-f]{28}$' THEN parent_envs:=parent_envs||jsonb_build_object('production',true);END IF;
parent_env:=parent_fact->'payment_proof'->>'environment';IF parent_env<>'' THEN parent_envs:=parent_envs||jsonb_build_object(parent_env,true);END IF;
FOR parent_confirmation IN SELECT value FROM jsonb_array_elements(parent_fact->'confirmations') LOOP
 IF parent_confirmation->>'audit_id'=ANY(parent_seen) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
 IF parent_confirmation->>'supersedes'<>'0' THEN
  IF NOT parent_leaves ? (parent_confirmation->>'supersedes') THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
  parent_leaves:=parent_leaves-(parent_confirmation->>'supersedes');
 END IF;
 parent_seen:=array_append(parent_seen,parent_confirmation->>'audit_id');parent_leaves:=parent_leaves||jsonb_build_object(parent_confirmation->>'audit_id',parent_confirmation->>'environment');
END LOOP;
FOR parent_env IN SELECT value#>>'{}' FROM jsonb_each(parent_leaves) LOOP parent_envs:=parent_envs||jsonb_build_object(parent_env,true);END LOOP;
IF (SELECT count(*) FROM jsonb_object_keys(parent_envs))<>1 OR NOT parent_envs ? p_environment THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
random_bytes:=uuid_send(gen_random_uuid());out_no:=(CASE p_environment WHEN 'uat' THEN 'OU1R' ELSE 'OP1R' END)||encode(substring(random_bytes FROM 1 FOR 6)||substring(random_bytes FROM 8 FOR 1)||substring(random_bytes FROM 10 FOR 7),'hex');req:=jsonb_build_object('out_refund_no',out_no,'reason',reason,'notify_url',notify,'amount_cents',p.expected_amount_cents,'total_cents',p.expected_amount_cents,'currency',p.currency);
raw_bytes:=p.out_trade_no;text_value:='';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN text_value:=text_value||chr(65533);i:=i+1;ELSE text_value:=text_value||convert_from(substring(raw_bytes,i+1,width),'UTF8');i:=i+width;END IF;END LOOP;provider_text:=text_value;
req:=req||jsonb_build_object('out_trade_no',provider_text);
req:=req||jsonb_build_object('transaction_id','');
raw_bytes:=p.out_trade_no;out_trade_json:='"';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN out_trade_json:=out_trade_json||E'\\ufffd';i:=i+1;ELSE json_piece:=replace(replace(replace(replace(replace(to_json(convert_from(substring(raw_bytes,i+1,width),'UTF8'))::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');out_trade_json:=out_trade_json||substring(json_piece,2,char_length(json_piece)-2);i:=i+width;END IF;END LOOP;out_trade_json:=out_trade_json||'"';
transaction_json:='""';
request_json:='{"out_trade_no":'||out_trade_json;
IF req->>'transaction_id'<>'' THEN request_json:=request_json||',"transaction_id":'||transaction_json;END IF;
request_json:=request_json||',"out_refund_no":'||replace(replace(replace(replace(replace(to_json(req->>'out_refund_no')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"reason":'||replace(replace(replace(replace(replace(to_json(req->>'reason')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"notify_url":'||replace(replace(replace(replace(replace(to_json(req->>'notify_url')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"amount_cents":'||(req->>'amount_cents')||',"total_cents":'||(req->>'total_cents')||',"currency":'||replace(replace(replace(replace(replace(to_json(req->>'currency')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||'}';
IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
pg_us:=mod((p_now->>'epoch_seconds')::numeric*1000000+div((p_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN now_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN now_at:='-infinity'::timestamptz;ELSE now_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
INSERT INTO public.refunds(prepayment_id,order_id,out_refund_no,idempotency_key_hash,amount_cents,currency,reason_code,requested_by_user_id,requested_by_account_id,provider_request_json,provider_request_digest,provider_state,create_attempted_at,provider_refund_id,materialization_state,pending_reason_code,materialized_at,lease_kind,lease_owner,lease_expires_at,record_version,next_query_at,created_at,updated_at) VALUES(payment_id,order_id,convert_to(out_no,'UTF8'),key_bytes,p.expected_amount_cents,p.currency,reason,CASE WHEN merchant THEN NULL ELSE p_actor END,CASE WHEN merchant THEN a.id ELSE NULL END,request_json::jsonb,sha256(convert_to(request_json,'UTF8')),'READY',NULL,NULL,'AWAITING_PROVIDER',NULL,NULL,NULL,NULL,NULL,1,NULL,now_at,now_at) RETURNING * INTO r;IF r.id=0 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
provider_text:='';receipt:=jsonb_build_object('ID',r.id,'PrepaymentID',r.prepayment_id,'OrderID',coalesce(r.order_id,0),'State',r.provider_state,'MaterializationState',r.materialization_state,'AmountCents',r.amount_cents,'Currency',r.currency,'RequestedAt',p_now->>'canonical','ProviderRefundID',provider_text,'PendingReason',coalesce(r.pending_reason_code,''));IF length(substring(p_now->>'canonical' FROM '^([0-9]+)-')) IS DISTINCT FROM 4 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
evidence:=encode(sha256(convert_to(coalesce(r.order_id,0)::text,'UTF8')||decode('00','hex')||convert_to(reason,'UTF8')),'hex');
INSERT INTO public.action_audits(entry_kind,actor_kind,actor_scope_hash,actor_user_id,actor_account_id,actor_account_id_snapshot,actor_role_snapshot,actor_auth_version_snapshot,action,target_type,target_id,operation_key_hash,request_id_hash,result,reason_code,before_state_json,after_state_json,response_json,occurred_at) VALUES('COMMAND_RECEIPT',CASE WHEN merchant THEN 'MERCHANT' ELSE 'USER' END,scope,p_actor,CASE WHEN merchant THEN a.id ELSE NULL END,CASE WHEN merchant THEN a.id ELSE NULL END,CASE WHEN merchant THEN a.role ELSE NULL END,CASE WHEN merchant THEN a.auth_version ELSE NULL END,'refund.request','REFUND',r.id,key_bytes,decode(p_request_hash,'hex'),'SUCCEEDED','REFUND_REQUESTED',jsonb_build_object('state',before_state,'request_digest',evidence),jsonb_build_object('state','REFUNDING'),receipt,now_at);RETURN jsonb_build_object('outcome','REQUESTED','receipt',receipt::text,'is_new',true,'refund_id',r.id::text,'prepayment_id',r.prepayment_id::text);
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state IN ('40P01','40001','55P03') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint','');END IF;
IF failure_state='23505' AND failure_constraint IN ('uq_refunds_prepayment','uq_refunds_order','uq_refunds_out_refund_no','uq_action_audits_command_receipt') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint',failure_constraint);END IF;
IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
RAISE;
 END;
END
$order_rpc$;

REVOKE ALL ON FUNCTION public.order_payment_prepare_v2(numeric,numeric,text,text,text,timestamptz,numeric,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.order_payment_prepare_v2(numeric,numeric,text,text,text,timestamptz,numeric,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.order_refund_request_order_v2(text,numeric,jsonb,text,text,text,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.order_refund_request_order_v2(text,numeric,jsonb,text,text,text,jsonb,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.order_refund_request_paid_v2(numeric,numeric,text,text,text,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.order_refund_request_paid_v2(numeric,numeric,text,text,text,jsonb,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.order_payment_prepare_v1(numeric,numeric,text,text,text,timestamptz,numeric,jsonb) FROM authenticated;
REVOKE ALL ON FUNCTION public.order_refund_request_order_v1(text,numeric,jsonb,text,text,text,jsonb,text) FROM authenticated;
REVOKE ALL ON FUNCTION public.order_refund_request_paid_v1(numeric,numeric,text,text,text,jsonb,text) FROM authenticated;


CREATE OR REPLACE FUNCTION public.order_billing_ownership_facts_v1(p_environment text,p_entries jsonb,p_evidence_cutoff numeric)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE entry jsonb;field record;req jsonb;p public.prepayments%ROWTYPE;r public.refunds%ROWTYPE;payment_proof jsonb;refund_proof jsonb;confirmations jsonb;results jsonb:='[]';cutoff numeric;canonical text;proof_state text;proof_env text;seen text[]:=ARRAY[]::text[];confirmation record;c jsonb;payment_found boolean;refund_found boolean;worker_locator boolean;resolved_parent_hex text;query_claim jsonb;result_fact jsonb;payment_locator boolean;resolved_provider_id_hex text;provider_count integer;proof_entry jsonb;system_locator boolean;resolved_payment_provider_id_hex text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 IF p_environment IS DISTINCT FROM '__ORDER_ENVIRONMENT__' OR p_environment NOT IN ('uat','production') OR p_evidence_cutoff IS NULL OR p_evidence_cutoff<0 OR p_evidence_cutoff>18446744073709551615 OR p_evidence_cutoff<>trunc(p_evidence_cutoff) OR jsonb_typeof(p_entries) IS DISTINCT FROM 'array' OR jsonb_array_length(p_entries)>100 THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 cutoff:=p_evidence_cutoff;
 IF cutoff=0 THEN SELECT coalesce(max(id),0) INTO cutoff FROM public.action_audits WHERE entry_kind='SYSTEM_EVIDENCE' AND actor_kind='SYSTEM' AND action='billing.ownership_confirmed';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(entry))<>8 OR NOT entry ?& ARRAY['ordinal','kind','appid_hex','mchid_hex','out_trade_no_hex','out_refund_no_hex','provider_id_hex','payment_provider_id_hex'] THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF jsonb_typeof(entry->'kind') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'ordinal') IS DISTINCT FROM 'string' OR entry->>'ordinal' !~ '^[1-9][0-9]*$' OR (entry->>'ordinal')::numeric>18446744073709551615 OR entry->>'ordinal'=ANY(seen) OR entry->>'kind' NOT IN ('PAYMENT','REFUND') THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  seen:=array_append(seen,entry->>'ordinal');
  FOR field IN SELECT key,value FROM jsonb_each(entry) WHERE key NOT IN ('ordinal','kind') LOOP
   IF jsonb_typeof(field.value) IS DISTINCT FROM 'string' OR field.value#>>'{}' !~ '^([0-9a-f]{2})*$' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   PERFORM convert_from(decode(field.value#>>'{}','hex'),'UTF8');
  END LOOP;
  payment_locator:=entry->>'kind'='PAYMENT' AND entry->>'provider_id_hex'='' AND entry->>'payment_provider_id_hex'='';
  proof_entry:=entry;
  worker_locator:=entry->>'kind'='REFUND' AND entry->>'out_trade_no_hex'='' AND entry->>'provider_id_hex'='' AND entry->>'payment_provider_id_hex'='';
  system_locator:=entry->>'kind'='REFUND' AND entry->>'out_trade_no_hex'='' AND entry->>'provider_id_hex'<>'' AND entry->>'payment_provider_id_hex'='';
  IF entry->>'appid_hex'='' OR entry->>'mchid_hex'='' OR (entry->>'out_trade_no_hex'='' AND NOT worker_locator AND NOT system_locator) OR (entry->>'kind'='PAYMENT' AND entry->>'out_refund_no_hex'<>'') OR (entry->>'kind'='REFUND' AND entry->>'out_refund_no_hex'='') THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  payment_proof:=jsonb_build_object('state','ABSENT','digest_hex','','environment','');refund_proof:=payment_proof;
  IF system_locator THEN
   SELECT * INTO r FROM public.refunds WHERE out_refund_no=decode(entry->>'out_refund_no_hex','hex') AND materialization_state='APPLIED' AND provider_refund_id=decode(entry->>'provider_id_hex','hex');
   IF NOT FOUND THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   SELECT * INTO p FROM public.prepayments WHERE id=r.prepayment_id;payment_found:=FOUND;
   IF NOT payment_found OR encode(p.expected_appid,'hex')<>entry->>'appid_hex' OR encode(p.expected_mchid,'hex')<>entry->>'mchid_hex' OR convert_from(p.out_trade_no,'UTF8') ~ (CASE WHEN p_environment='uat' THEN '^OP1[PR][0-9a-f]{28}$' ELSE '^OU1[PR][0-9a-f]{28}$' END) OR convert_from(r.out_refund_no,'UTF8') ~ (CASE WHEN p_environment='uat' THEN '^OP1[PR][0-9a-f]{28}$' ELSE '^OU1[PR][0-9a-f]{28}$' END) THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   resolved_parent_hex:=encode(p.out_trade_no,'hex');resolved_payment_provider_id_hex:=encode(convert_to(coalesce(r.provider_request_json->>'transaction_id',''),'UTF8'),'hex');
   proof_entry:=entry||jsonb_build_object('out_trade_no_hex',resolved_parent_hex,'payment_provider_id_hex',resolved_payment_provider_id_hex);
  ELSIF worker_locator THEN
   SELECT * INTO r FROM public.refunds WHERE out_refund_no=decode(entry->>'out_refund_no_hex','hex');
   IF NOT FOUND OR r.lease_kind IS DISTINCT FROM 'QUERY' OR r.lease_expires_at IS NULL OR r.lease_expires_at<=clock_timestamp() OR r.lease_owner IS NULL OR octet_length(r.lease_owner)<>16 OR r.record_version NOT BETWEEN 1 AND 18446744073709551615 THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   query_claim:=jsonb_build_object('version',r.record_version::text,'owner_hex',encode(r.lease_owner,'hex'));
   SELECT * INTO p FROM public.prepayments WHERE id=r.prepayment_id;payment_found:=FOUND;
   IF NOT payment_found THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   resolved_parent_hex:=encode(p.out_trade_no,'hex');
  ELSE
   SELECT * INTO p FROM public.prepayments WHERE out_trade_no=decode(entry->>'out_trade_no_hex','hex');payment_found:=FOUND;
  END IF;
  IF payment_locator THEN
   IF NOT payment_found OR encode(p.expected_appid,'hex')<>entry->>'appid_hex' OR encode(p.expected_mchid,'hex')<>entry->>'mchid_hex' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   IF EXISTS(SELECT 1 FROM public.payment_observations o WHERE o.prepayment_id=p.id AND o.validation='MATCH' AND (o.provider_state IS DISTINCT FROM 'PAID' OR o.out_trade_no IS DISTINCT FROM p.out_trade_no OR o.transaction_id IS NULL OR octet_length(o.transaction_id)=0 OR o.amount_cents IS DISTINCT FROM p.expected_amount_cents OR o.currency IS DISTINCT FROM p.currency OR o.success_time IS NULL)) THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   SELECT count(DISTINCT o.transaction_id),min(encode(o.transaction_id,'hex')) INTO provider_count,resolved_provider_id_hex FROM public.payment_observations o WHERE o.prepayment_id=p.id AND o.validation='MATCH';
   IF provider_count>1 THEN RETURN jsonb_build_object('outcome','CONFLICT');END IF;
   IF provider_count<>1 OR resolved_provider_id_hex IS NULL OR resolved_provider_id_hex='' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   proof_entry:=entry||jsonb_build_object('provider_id_hex',resolved_provider_id_hex,'payment_provider_id_hex',resolved_provider_id_hex);
  END IF;
  IF payment_found THEN
   req:=p.provider_create_request_json;proof_state:='CORRUPT';proof_env:='';
   IF jsonb_typeof(req)='object' AND (SELECT count(*) FROM jsonb_object_keys(req))=11 AND req ?& ARRAY['appid','mchid','description','out_trade_no','time_expire','notify_url','amount_cents','currency','payer_openid','quote_id','quote_digest'] AND NOT EXISTS(SELECT 1 FROM jsonb_each(req) f WHERE (f.key='amount_cents' AND jsonb_typeof(f.value)<>'number') OR (f.key<>'amount_cents' AND jsonb_typeof(f.value)<>'string')) AND req->>'amount_cents' ~ '^[1-9][0-9]*$' THEN
    canonical:='{'||'"appid":'||replace(replace(replace(replace(replace(to_json(req->>'appid')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"mchid":'||replace(replace(replace(replace(replace(to_json(req->>'mchid')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"description":'||replace(replace(replace(replace(replace(to_json(req->>'description')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"out_trade_no":'||replace(replace(replace(replace(replace(to_json(req->>'out_trade_no')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"time_expire":'||replace(replace(replace(replace(replace(to_json(req->>'time_expire')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"notify_url":'||replace(replace(replace(replace(replace(to_json(req->>'notify_url')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"amount_cents":'||(req->>'amount_cents')||',"currency":'||replace(replace(replace(replace(replace(to_json(req->>'currency')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"payer_openid":'||replace(replace(replace(replace(replace(to_json(req->>'payer_openid')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"quote_id":'||replace(replace(replace(replace(replace(to_json(req->>'quote_id')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"quote_digest":'||replace(replace(replace(replace(replace(to_json(req->>'quote_digest')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||'}';
    IF sha256(convert_to(canonical,'UTF8'))=p.provider_create_request_digest AND convert_to(req->>'out_trade_no','UTF8')=p.out_trade_no AND convert_to(req->>'appid','UTF8')=p.expected_appid AND convert_to(req->>'mchid','UTF8')=p.expected_mchid AND (req->>'amount_cents')::numeric=p.expected_amount_cents AND req->>'currency'=p.currency THEN
     proof_state:='VALID';IF p.expected_appid<>decode(entry->>'appid_hex','hex') OR p.expected_mchid<>decode(entry->>'mchid_hex','hex') THEN proof_state:='CONFLICT';ELSIF req->>'notify_url'='__ORDER_PAYMENT_NOTIFY_URL__' THEN proof_env:=p_environment;END IF;
    END IF;
   END IF;
   payment_proof:=jsonb_build_object('state',proof_state,'digest_hex',encode(p.provider_create_request_digest,'hex'),'environment',proof_env);
  END IF;
  IF entry->>'kind'='REFUND' THEN
   SELECT * INTO r FROM public.refunds WHERE out_refund_no=decode(entry->>'out_refund_no_hex','hex');refund_found:=FOUND;
   IF refund_found THEN
    req:=r.provider_request_json;proof_state:='CORRUPT';proof_env:='';
    IF jsonb_typeof(req)='object' AND (SELECT count(*) FROM jsonb_object_keys(req))=(CASE WHEN req ? 'transaction_id' THEN 8 ELSE 7 END) AND req ?& ARRAY['out_trade_no','out_refund_no','reason','notify_url','amount_cents','total_cents','currency'] AND NOT EXISTS(SELECT 1 FROM jsonb_each(req) f WHERE (f.key IN ('amount_cents','total_cents') AND jsonb_typeof(f.value)<>'number') OR (f.key NOT IN ('amount_cents','total_cents') AND jsonb_typeof(f.value)<>'string')) AND req->>'amount_cents' ~ '^[1-9][0-9]*$' AND req->>'total_cents' ~ '^[1-9][0-9]*$' THEN
     canonical:='{"out_trade_no":'||replace(replace(replace(replace(replace(to_json(req->>'out_trade_no')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||(CASE WHEN coalesce(req->>'transaction_id','')<>'' THEN ',"transaction_id":'||replace(replace(replace(replace(replace(to_json(req->>'transaction_id')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029') ELSE '' END)||',"out_refund_no":'||replace(replace(replace(replace(replace(to_json(req->>'out_refund_no')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"reason":'||replace(replace(replace(replace(replace(to_json(req->>'reason')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"notify_url":'||replace(replace(replace(replace(replace(to_json(req->>'notify_url')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"amount_cents":'||(req->>'amount_cents')||',"total_cents":'||(req->>'total_cents')||',"currency":'||replace(replace(replace(replace(replace(to_json(req->>'currency')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||'}';
     IF sha256(convert_to(canonical,'UTF8'))=r.provider_request_digest AND convert_to(req->>'out_refund_no','UTF8')=r.out_refund_no AND (req->>'amount_cents')::numeric=r.amount_cents AND (req->>'total_cents')::numeric=r.amount_cents AND req->>'currency'=r.currency THEN
      proof_state:='VALID';IF NOT payment_found OR r.prepayment_id<>p.id OR convert_to(req->>'out_trade_no','UTF8')<>p.out_trade_no OR (NOT worker_locator AND r.provider_refund_id IS NOT NULL AND r.provider_refund_id<>decode(entry->>'provider_id_hex','hex')) OR (NOT worker_locator AND NOT system_locator AND coalesce(req->>'transaction_id','')<>'' AND convert_to(req->>'transaction_id','UTF8')<>decode(entry->>'payment_provider_id_hex','hex')) THEN proof_state:='CONFLICT';ELSIF req->>'notify_url'='__ORDER_REFUND_NOTIFY_URL__' THEN proof_env:=p_environment;END IF;
     END IF;
    END IF;
    refund_proof:=jsonb_build_object('state',proof_state,'digest_hex',encode(r.provider_request_digest,'hex'),'environment',proof_env);
   END IF;
  END IF;
  confirmations:='[]';
  FOR confirmation IN SELECT id,after_state_json FROM public.action_audits WHERE entry_kind='SYSTEM_EVIDENCE' AND actor_kind='SYSTEM' AND action='billing.ownership_confirmed' AND id<=cutoff AND after_state_json->'entry'=proof_entry-'ordinal' ORDER BY id LOOP
   c:=confirmation.after_state_json;
   IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(c))<>6 OR NOT c ?& ARRAY['rule_version','entry','environment','source_ref_hex','evidence_sha256','supersedes'] OR c->>'rule_version'<>'1' OR c->>'environment' NOT IN ('uat','production') OR c->>'source_ref_hex' !~ '^([0-9a-f]{2})+$' OR c->>'evidence_sha256' !~ '^[0-9a-f]{64}$' OR c->>'supersedes' !~ '^(0|[1-9][0-9]*)$' OR (c->>'supersedes')::numeric>=confirmation.id THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   IF EXISTS(SELECT 1 FROM jsonb_each(c) f WHERE f.key<>'entry' AND jsonb_typeof(f.value) IS DISTINCT FROM 'string') THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   PERFORM convert_from(decode(c->>'source_ref_hex','hex'),'UTF8');
   confirmations:=confirmations||jsonb_build_array(jsonb_build_object('audit_id',confirmation.id::text,'environment',c->>'environment','source_ref_hex',c->>'source_ref_hex','evidence_sha256',c->>'evidence_sha256','supersedes',c->>'supersedes'));
  END LOOP;
  result_fact:=jsonb_build_object('entry',entry,'payment_proof',payment_proof,'refund_proof',refund_proof,'confirmations',confirmations);
  IF system_locator THEN result_fact:=result_fact||jsonb_build_object('resolved_parent_hex',resolved_parent_hex,'resolved_payment_provider_id_hex',resolved_payment_provider_id_hex);END IF;
  IF payment_locator THEN result_fact:=result_fact||jsonb_build_object('resolved_provider_id_hex',resolved_provider_id_hex);END IF;
  IF worker_locator THEN result_fact:=result_fact||jsonb_build_object('resolved_parent_hex',resolved_parent_hex,'query_claim',query_claim);END IF;
  results:=results||jsonb_build_array(result_fact);
 END LOOP;
 RETURN jsonb_build_object('outcome','FOUND','evidence_cutoff',cutoff::text,'entries',results);
EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire OR numeric_value_out_of_range THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');
END
$order_rpc$;
REVOKE ALL ON FUNCTION public.order_billing_ownership_facts_v1(text,jsonb,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.order_billing_ownership_facts_v1(text,jsonb,numeric) TO authenticated;

CREATE OR REPLACE FUNCTION public.order_billing_reconcile_v2(p_date text,p_digest_hex text,p_matched numeric,p_provider_only jsonb,p_system_only jsonb,p_environment text,p_evidence jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE intrinsic bytea;lock_unsigned numeric;position integer;existing_id numeric;entry jsonb;target_id numeric;payment_ids numeric[]:='{}'::numeric[];refund_ids numeric[]:='{}'::numeric[];evidence jsonb;audit_result text;reason text;audit_at timestamptz;detail jsonb;proof jsonb;proofs text[]:=ARRAY[]::text[];computed_digest text;facts_reply jsonb;batch jsonb:='[]';batch_expected jsonb:='[]';detail_count integer:=0;cutoff numeric;unknown boolean:=false;has_this boolean;ordinal_seen numeric[]:=ARRAY[]::numeric[];projection record;system_entry jsonb;system_identity jsonb;proven_entries jsonb;check_batch record;class_envs jsonb;class_leaves jsonb;class_seen text[];class_confirm jsonb;class_env text;number_env text;parent_env text;expected_class text;expected_basis text;class_number text;class_parent text;class_kind text;summary_expected jsonb;projection_expected jsonb;system_expected jsonb:='[]';system_fact jsonb;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
 -- Go constructed date.Format + NUL + digest before BeginTx. Date is hash material, not a new calendar parser.
 IF p_date IS NULL OR p_digest_hex IS NULL OR p_digest_hex !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;

 IF p_environment IS DISTINCT FROM '__ORDER_ENVIRONMENT__' OR p_environment NOT IN ('uat','production') OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_evidence))<>14 OR NOT p_evidence ?& ARRAY['rule_version','environment','merchant_id','appid','date','bill_digest','evidence_cutoff','evidence_digest','details','summary','matched','provider_only','system_only','system_facts'] OR p_evidence->>'rule_version'<>'1' OR p_evidence->>'environment'<>p_environment OR p_evidence->>'appid'<>'wx15e136b256d4dc5a' OR coalesce(p_evidence->>'merchant_id','')='' OR p_evidence->>'date'<>p_date OR p_evidence->>'bill_digest'<>p_digest_hex OR p_evidence->>'evidence_digest' !~ '^[0-9a-f]{64}$' OR p_evidence->>'evidence_cutoff' !~ '^(0|[1-9][0-9]*)$' OR jsonb_typeof(p_evidence->'details') IS DISTINCT FROM 'array' OR jsonb_typeof(p_evidence->'summary') IS DISTINCT FROM 'array' OR (p_evidence->>'matched')::numeric IS DISTINCT FROM p_matched THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 cutoff:=(p_evidence->>'evidence_cutoff')::numeric;
 intrinsic:=sha256(convert_to('{'||'"rule_version":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'rule_version')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"environment":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'environment')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"merchant_id":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'merchant_id')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"date":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'date')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"bill_digest":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'bill_digest')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||',"evidence_digest":'||replace(replace(replace(replace(replace(to_json(p_evidence->>'evidence_digest')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||'}','UTF8'));

 lock_unsigned:=0;FOR position IN 0..7 LOOP lock_unsigned:=lock_unsigned*256+get_byte(intrinsic,position);END LOOP;
 IF lock_unsigned>=9223372036854775808 THEN lock_unsigned:=lock_unsigned-18446744073709551616;END IF;
 PERFORM set_config('lock_timeout','5s',true);
 PERFORM pg_advisory_xact_lock(lock_unsigned::bigint);
 FOR detail IN SELECT value FROM jsonb_array_elements(p_evidence->'details') LOOP
  detail_count:=detail_count+1;proof:=detail->'proof';
  IF jsonb_typeof(detail->'detail') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(detail->'detail'))<>12 OR NOT (detail->'detail') ?& ARRAY['Ordinal','Kind','AppID','MerchantID','OutTradeNo','OutRefundNo','ProviderID','PaymentProviderID','AmountCents','Currency','State','OccurredAt'] THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(detail->'detail') f WHERE f.key NOT IN ('Ordinal','AmountCents') AND jsonb_typeof(f.value) IS DISTINCT FROM 'string') OR jsonb_typeof(detail->'detail'->'Ordinal') IS DISTINCT FROM 'number' OR detail->'detail'->>'AppID'='' OR detail->'detail'->>'OutTradeNo'='' OR detail->'detail'->>'ProviderID'='' OR detail->'detail'->>'PaymentProviderID'='' OR detail->'detail'->>'Kind' NOT IN ('PAYMENT','REFUND') OR (detail->'detail'->>'Kind'='PAYMENT' AND detail->'detail'->>'OutRefundNo'<>'') OR (detail->'detail'->>'Kind'='REFUND' AND detail->'detail'->>'OutRefundNo'='') OR detail->'detail'->>'OccurredAt' IN ('','0001-01-01T00:00:00Z') THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF jsonb_typeof(detail) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(detail)) IS DISTINCT FROM 4 OR NOT detail ?& ARRAY['detail','class','basis','proof'] OR detail->>'class' NOT IN ('THIS_ENV','PROVEN_OTHER','UNKNOWN') OR (detail->'detail'->>'Ordinal')::numeric IS DISTINCT FROM detail_count OR proof->'entry'->>'ordinal' IS DISTINCT FROM detail_count::text OR detail->'detail'->>'Kind' IS DISTINCT FROM proof->'entry'->>'kind' OR encode(convert_to(detail->'detail'->>'AppID','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'appid_hex' OR detail->'detail'->>'MerchantID' IS DISTINCT FROM p_evidence->>'merchant_id' OR encode(convert_to(detail->'detail'->>'MerchantID','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'mchid_hex' OR encode(convert_to(detail->'detail'->>'OutTradeNo','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'out_trade_no_hex' OR encode(convert_to(detail->'detail'->>'OutRefundNo','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'out_refund_no_hex' OR encode(convert_to(detail->'detail'->>'ProviderID','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'provider_id_hex' OR encode(convert_to(detail->'detail'->>'PaymentProviderID','UTF8'),'hex') IS DISTINCT FROM proof->'entry'->>'payment_provider_id_hex' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF jsonb_typeof(detail->'detail'->'AmountCents') IS DISTINCT FROM 'number' OR (detail->'detail'->>'AmountCents')::numeric NOT BETWEEN 1 AND 18446744073709551615 OR trunc((detail->'detail'->>'AmountCents')::numeric)<>(detail->'detail'->>'AmountCents')::numeric OR detail->'detail'->>'Currency'<>'CNY' OR (detail->'detail'->>'Kind'='PAYMENT' AND detail->'detail'->>'State'<>'SUCCESS') OR (detail->'detail'->>'Kind'='REFUND' AND detail->'detail'->>'State' NOT IN ('SUCCESS','PROCESSING','FAIL','CHANGE')) THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  class_envs:='{}';class_leaves:='{}';class_seen:=ARRAY[]::text[];expected_class:='UNKNOWN';expected_basis:='UNPROVEN_OR_CONFLICTING';number_env:='';parent_env:='';
  class_kind:=detail->'detail'->>'Kind';class_parent:=detail->'detail'->>'OutTradeNo';class_number:=CASE WHEN class_kind='PAYMENT' THEN class_parent ELSE detail->'detail'->>'OutRefundNo' END;
  IF proof->'payment_proof'->>'state' IN ('CORRUPT','CONFLICT') OR proof->'refund_proof'->>'state' IN ('CORRUPT','CONFLICT') THEN expected_basis:='INVALID_IMMUTABLE_PROOF';
  ELSE
   IF detail->'detail'->>'AppID'=p_evidence->>'appid' THEN
    IF class_number ~ (CASE WHEN class_kind='PAYMENT' THEN '^OU1P[0-9a-f]{28}$' ELSE '^OU1R[0-9a-f]{28}$' END) THEN number_env:='uat';ELSIF class_number ~ (CASE WHEN class_kind='PAYMENT' THEN '^OP1P[0-9a-f]{28}$' ELSE '^OP1R[0-9a-f]{28}$' END) THEN number_env:='production';END IF;
   END IF;
   IF class_parent ~ '^OU1P[0-9a-f]{28}$' THEN parent_env:='uat';ELSIF class_parent ~ '^OP1P[0-9a-f]{28}$' THEN parent_env:='production';END IF;
   IF number_env<>'' THEN class_envs:=class_envs||jsonb_build_object(number_env,true);END IF;
   IF class_kind='REFUND' AND number_env<>'' AND ((parent_env<>'' AND parent_env<>number_env) OR class_parent ~ '^O[UP]1R[0-9a-f]{28}$') THEN expected_basis:='PARENT_CONFLICT';
   ELSE
    IF proof->'payment_proof'->>'state'='VALID' AND proof->'payment_proof'->>'environment'<>'' THEN
     class_env:=proof->'payment_proof'->>'environment';
     IF class_kind='PAYMENT' THEN class_envs:=class_envs||jsonb_build_object(class_env,true);
     ELSIF proof->'refund_proof'->>'state'='VALID' AND proof->'refund_proof'->>'environment'<>'' THEN
      IF proof->'refund_proof'->>'environment'<>class_env THEN expected_basis:='PARENT_CONFLICT';ELSE class_envs:=class_envs||jsonb_build_object(class_env,true);END IF;
     ELSIF (class_number ~ '^OU1[PR][0-9a-f]{28}$' AND class_env<>'uat') OR (class_number ~ '^OP1[PR][0-9a-f]{28}$' AND class_env<>'production') THEN expected_basis:='PARENT_CONFLICT';END IF;
    END IF;
    IF expected_basis<>'PARENT_CONFLICT' THEN
     FOR class_confirm IN SELECT value FROM jsonb_array_elements(proof->'confirmations') LOOP
      IF class_confirm->>'audit_id'=ANY(class_seen) OR (class_confirm->>'supersedes'<>'0' AND NOT class_leaves ? (class_confirm->>'supersedes')) THEN expected_basis:='CONFIRMATION_CONFLICT';EXIT;END IF;
      IF class_confirm->>'supersedes'<>'0' THEN class_leaves:=class_leaves-(class_confirm->>'supersedes');END IF;
      class_seen:=array_append(class_seen,class_confirm->>'audit_id');class_leaves:=class_leaves||jsonb_build_object(class_confirm->>'audit_id',class_confirm->>'environment');
     END LOOP;
     IF expected_basis<>'CONFIRMATION_CONFLICT' THEN
      IF (SELECT count(DISTINCT value) FROM jsonb_each_text(class_leaves))>1 THEN expected_basis:='CONFIRMATION_CONFLICT';
      ELSE
       FOR class_env IN SELECT value FROM jsonb_each_text(class_leaves) LOOP class_envs:=class_envs||jsonb_build_object(class_env,true);END LOOP;
       IF (SELECT count(*) FROM jsonb_object_keys(class_envs))=1 THEN expected_class:=CASE WHEN class_envs ? p_environment THEN 'THIS_ENV' ELSE 'PROVEN_OTHER' END;expected_basis:='PROVEN';END IF;
      END IF;
     END IF;
    END IF;
   END IF;
  END IF;
  IF detail->>'class' IS DISTINCT FROM expected_class OR detail->>'basis' IS DISTINCT FROM expected_basis THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF detail->>'class'='UNKNOWN' THEN unknown:=true;END IF;
 END LOOP;
 IF jsonb_typeof(p_evidence->'provider_only') IS DISTINCT FROM 'array' OR jsonb_typeof(p_evidence->'system_only') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p_evidence->'details') d WHERE d->>'class'='THIS_ENV' AND d->'detail'->>'State'='SUCCESS') <> p_matched+jsonb_array_length(p_evidence->'provider_only') THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('class',g.c,'environment',g.e,'kind',g.k,'currency',g.currency,'state',g.state,'count',g.n,'amount_cents',g.amount) ORDER BY g.c||'/'||g.e||'/'||g.k||'/'||g.currency||'/'||g.state),'[]'::jsonb) INTO summary_expected FROM (SELECT d->>'class' c,CASE WHEN d->>'class'='THIS_ENV' THEN p_environment WHEN d->>'class'='PROVEN_OTHER' THEN CASE WHEN p_environment='uat' THEN 'production' ELSE 'uat' END ELSE '' END e,d->'detail'->>'Kind' k,d->'detail'->>'Currency' currency,d->'detail'->>'State' state,count(*) n,sum((d->'detail'->>'AmountCents')::numeric) amount FROM jsonb_array_elements(p_evidence->'details') d GROUP BY 1,2,3,4,5) g;
 IF summary_expected IS DISTINCT FROM p_evidence->'summary' OR EXISTS(SELECT 1 FROM jsonb_array_elements(summary_expected) s WHERE (s->>'amount_cents')::numeric>18446744073709551615) THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',d->>'kind','out_trade_no_hex',encode(convert_to(coalesce(d->>'out_trade_no',''),'UTF8'),'hex'),'out_refund_no_hex',encode(convert_to(coalesce(d->>'out_refund_no',''),'UTF8'),'hex'))),'[]'::jsonb) INTO projection_expected FROM jsonb_array_elements(p_evidence->'provider_only') d;
 IF projection_expected IS DISTINCT FROM p_provider_only THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',d->>'kind','out_trade_no_hex',encode(convert_to(coalesce(d->>'out_trade_no',''),'UTF8'),'hex'),'out_refund_no_hex',encode(convert_to(coalesce(d->>'out_refund_no',''),'UTF8'),'hex'))),'[]'::jsonb) INTO projection_expected FROM jsonb_array_elements(p_evidence->'system_only') d;
 IF projection_expected IS DISTINCT FROM p_system_only THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 -- Assemble each <=100 identity batch once, instead of repeatedly copying
 -- growing JSONB arrays for every row of the supported full bill.
 FOR check_batch IN SELECT jsonb_agg(d.value->'proof'->'entry' ORDER BY d.position) AS entries,jsonb_agg(d.value->'proof' ORDER BY d.position) AS expected FROM jsonb_array_elements(p_evidence->'details') WITH ORDINALITY d(value,position) GROUP BY (d.position-1)/100 ORDER BY (d.position-1)/100 LOOP
  facts_reply:=public.order_billing_ownership_facts_v1(p_environment,check_batch.entries,cutoff);
  IF facts_reply->>'outcome' IS DISTINCT FROM 'FOUND' OR (facts_reply->>'evidence_cutoff')::numeric IS DISTINCT FROM cutoff OR facts_reply->'entries' IS DISTINCT FROM check_batch.expected THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 END LOOP;
 IF detail_count=0 THEN
  facts_reply:=public.order_billing_ownership_facts_v1(p_environment,'[]'::jsonb,cutoff);
  IF facts_reply->>'outcome' IS DISTINCT FROM 'FOUND' OR (facts_reply->>'evidence_cutoff')::numeric IS DISTINCT FROM cutoff OR facts_reply->'entries' IS DISTINCT FROM '[]'::jsonb THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 END IF;
 IF jsonb_typeof(p_evidence->'system_facts') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 FOR system_entry IN SELECT value FROM jsonb_array_elements(p_evidence->'system_only') ORDER BY value->>'kind',CASE WHEN value->>'kind'='PAYMENT' THEN value->>'out_trade_no' ELSE value->>'out_refund_no' END LOOP
  system_identity:=jsonb_build_object('ordinal','1','kind',system_entry->>'kind','appid_hex',encode(convert_to(p_evidence->>'appid','UTF8'),'hex'),'mchid_hex',encode(convert_to(p_evidence->>'merchant_id','UTF8'),'hex'),'out_trade_no_hex',encode(convert_to(coalesce(system_entry->>'out_trade_no',''),'UTF8'),'hex'),'out_refund_no_hex',encode(convert_to(coalesce(system_entry->>'out_refund_no',''),'UTF8'),'hex'),'provider_id_hex',encode(convert_to(system_entry->>'provider_id','UTF8'),'hex'),'payment_provider_id_hex',CASE WHEN system_entry->>'kind'='PAYMENT' THEN encode(convert_to(system_entry->>'provider_id','UTF8'),'hex') ELSE '' END);
  IF system_entry->>'kind'='REFUND' THEN
   facts_reply:=public.order_billing_ownership_facts_v1(p_environment,jsonb_build_array(system_identity),cutoff);
   IF facts_reply->>'outcome'='UNAVAILABLE' THEN CONTINUE;END IF;
   IF facts_reply->>'outcome' IS DISTINCT FROM 'FOUND' OR (facts_reply->>'evidence_cutoff')::numeric IS DISTINCT FROM cutoff THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   system_identity:=system_identity||jsonb_build_object('out_trade_no_hex',facts_reply->'entries'->0->>'resolved_parent_hex','payment_provider_id_hex',facts_reply->'entries'->0->>'resolved_payment_provider_id_hex');
  END IF;
  facts_reply:=public.order_billing_ownership_facts_v1(p_environment,jsonb_build_array(system_identity),cutoff);
  IF facts_reply->>'outcome' IS DISTINCT FROM 'FOUND' OR (facts_reply->>'evidence_cutoff')::numeric IS DISTINCT FROM cutoff OR jsonb_array_length(facts_reply->'entries')<>1 THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  system_expected:=system_expected||(facts_reply->'entries');
 END LOOP;
 IF system_expected IS DISTINCT FROM p_evidence->'system_facts' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 -- Matched facts contain only ASCII hex, fixed enums and canonical decimals;
 -- this ordered aggregation therefore has exactly the Go JSON wire bytes.

 SELECT encode(sha256(convert_to('{"bill_facts":['||coalesce(string_agg('{"entry":'||'{'||'"ordinal":'||'"'||((ordered_proofs.proof->'entry')->>'ordinal')||'"'||',"kind":'||'"'||((ordered_proofs.proof->'entry')->>'kind')||'"'||',"appid_hex":'||'"'||((ordered_proofs.proof->'entry')->>'appid_hex')||'"'||',"mchid_hex":'||'"'||((ordered_proofs.proof->'entry')->>'mchid_hex')||'"'||',"out_trade_no_hex":'||'"'||((ordered_proofs.proof->'entry')->>'out_trade_no_hex')||'"'||',"out_refund_no_hex":'||'"'||((ordered_proofs.proof->'entry')->>'out_refund_no_hex')||'"'||',"provider_id_hex":'||'"'||((ordered_proofs.proof->'entry')->>'provider_id_hex')||'"'||',"payment_provider_id_hex":'||'"'||((ordered_proofs.proof->'entry')->>'payment_provider_id_hex')||'"'||'}'||',"payment_proof":'||'{'||'"state":'||'"'||((ordered_proofs.proof->'payment_proof')->>'state')||'"'||',"digest_hex":'||'"'||((ordered_proofs.proof->'payment_proof')->>'digest_hex')||'"'||',"environment":'||'"'||((ordered_proofs.proof->'payment_proof')->>'environment')||'"'||'}'||',"refund_proof":'||'{'||'"state":'||'"'||((ordered_proofs.proof->'refund_proof')->>'state')||'"'||',"digest_hex":'||'"'||((ordered_proofs.proof->'refund_proof')->>'digest_hex')||'"'||',"environment":'||'"'||((ordered_proofs.proof->'refund_proof')->>'environment')||'"'||'}'||',"confirmations":['||coalesce((SELECT string_agg('{'||'"audit_id":'||'"'||(c.value->>'audit_id')||'"'||',"environment":'||'"'||(c.value->>'environment')||'"'||',"source_ref_hex":'||'"'||(c.value->>'source_ref_hex')||'"'||',"evidence_sha256":'||'"'||(c.value->>'evidence_sha256')||'"'||',"supersedes":'||'"'||(c.value->>'supersedes')||'"'||'}',',' ORDER BY c.position) FROM jsonb_array_elements(ordered_proofs.proof->'confirmations') WITH ORDINALITY c(value,position)),'')||']}',',' ORDER BY ordered_proofs.position) FILTER (WHERE ordered_proofs.segment='bill'),'')||'],"system_facts":['||coalesce(string_agg('{"entry":'||'{'||'"ordinal":'||'"'||((ordered_proofs.proof->'entry')->>'ordinal')||'"'||',"kind":'||'"'||((ordered_proofs.proof->'entry')->>'kind')||'"'||',"appid_hex":'||'"'||((ordered_proofs.proof->'entry')->>'appid_hex')||'"'||',"mchid_hex":'||'"'||((ordered_proofs.proof->'entry')->>'mchid_hex')||'"'||',"out_trade_no_hex":'||'"'||((ordered_proofs.proof->'entry')->>'out_trade_no_hex')||'"'||',"out_refund_no_hex":'||'"'||((ordered_proofs.proof->'entry')->>'out_refund_no_hex')||'"'||',"provider_id_hex":'||'"'||((ordered_proofs.proof->'entry')->>'provider_id_hex')||'"'||',"payment_provider_id_hex":'||'"'||((ordered_proofs.proof->'entry')->>'payment_provider_id_hex')||'"'||'}'||',"payment_proof":'||'{'||'"state":'||'"'||((ordered_proofs.proof->'payment_proof')->>'state')||'"'||',"digest_hex":'||'"'||((ordered_proofs.proof->'payment_proof')->>'digest_hex')||'"'||',"environment":'||'"'||((ordered_proofs.proof->'payment_proof')->>'environment')||'"'||'}'||',"refund_proof":'||'{'||'"state":'||'"'||((ordered_proofs.proof->'refund_proof')->>'state')||'"'||',"digest_hex":'||'"'||((ordered_proofs.proof->'refund_proof')->>'digest_hex')||'"'||',"environment":'||'"'||((ordered_proofs.proof->'refund_proof')->>'environment')||'"'||'}'||',"confirmations":['||coalesce((SELECT string_agg('{'||'"audit_id":'||'"'||(c.value->>'audit_id')||'"'||',"environment":'||'"'||(c.value->>'environment')||'"'||',"source_ref_hex":'||'"'||(c.value->>'source_ref_hex')||'"'||',"evidence_sha256":'||'"'||(c.value->>'evidence_sha256')||'"'||',"supersedes":'||'"'||(c.value->>'supersedes')||'"'||'}',',' ORDER BY c.position) FROM jsonb_array_elements(ordered_proofs.proof->'confirmations') WITH ORDINALITY c(value,position)),'')||']}',',' ORDER BY ordered_proofs.position) FILTER (WHERE ordered_proofs.segment='system'),'')||']}','UTF8')),'hex') INTO computed_digest FROM (SELECT d.value->'proof' AS proof,d.position,'bill'::text AS segment FROM jsonb_array_elements(p_evidence->'details') WITH ORDINALITY d(value,position) UNION ALL SELECT d.value AS proof,d.position,'system'::text FROM jsonb_array_elements(p_evidence->'system_facts') WITH ORDINALITY d(value,position)) ordered_proofs;
 IF computed_digest IS DISTINCT FROM p_evidence->>'evidence_digest' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 SELECT id INTO existing_id FROM public.action_audits WHERE entry_kind='SYSTEM_EVIDENCE' AND actor_kind='PROVIDER' AND action='billing.reconcile' AND target_key_hash=intrinsic ORDER BY id LIMIT 1;
 IF FOUND THEN
 IF existing_id IS NULL OR existing_id NOT BETWEEN 0 AND 18446744073709551615 OR trunc(existing_id)<>existing_id THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  -- Original duplicate commits before projecting entries or sampling the independent audit clock.
  RETURN jsonb_build_object('outcome','RECONCILED');
 END IF;
 IF jsonb_typeof(p_provider_only) IS DISTINCT FROM 'array' OR jsonb_typeof(p_system_only) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
 -- Build the current-environment successful target set once. Re-scanning the
 -- complete bill for each difference makes a full supported bill quadratic.
 SELECT coalesce(jsonb_object_agg((d->'detail'->>'Kind')||':'||(CASE WHEN d->'detail'->>'Kind'='PAYMENT' THEN d->'proof'->'entry'->>'out_trade_no_hex' ELSE d->'proof'->'entry'->>'out_refund_no_hex' END),true),'{}'::jsonb) INTO proven_entries FROM jsonb_array_elements(p_evidence->'details') d WHERE d->>'class'='THIS_ENV' AND d->'detail'->>'State'='SUCCESS';
 FOR projection IN SELECT value,true AS provider FROM jsonb_array_elements(p_provider_only) UNION ALL SELECT value,false AS provider FROM jsonb_array_elements(p_system_only) LOOP
  entry:=projection.value;
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR NOT (entry ?& ARRAY['kind','out_trade_no_hex','out_refund_no_hex']) OR (entry-ARRAY['kind','out_trade_no_hex','out_refund_no_hex'])<>'{}'::jsonb OR jsonb_typeof(entry->'kind') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'out_trade_no_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'out_refund_no_hex') IS DISTINCT FROM 'string' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;

  has_this:=false;
  IF projection.provider THEN
   has_this:=proven_entries ? ((entry->>'kind')||':'||(CASE WHEN entry->>'kind'='PAYMENT' THEN entry->>'out_trade_no_hex' ELSE entry->>'out_refund_no_hex' END));
  ELSE
   SELECT value INTO system_entry FROM jsonb_array_elements(p_evidence->'system_only') WHERE value->>'kind'=entry->>'kind' AND (CASE WHEN entry->>'kind'='PAYMENT' THEN encode(convert_to(value->>'out_trade_no','UTF8'),'hex')=entry->>'out_trade_no_hex' ELSE encode(convert_to(value->>'out_refund_no','UTF8'),'hex')=entry->>'out_refund_no_hex' END);
   IF NOT FOUND THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   SELECT value INTO proof FROM jsonb_array_elements(p_evidence->'system_facts') WHERE value->'entry'->>'kind'=entry->>'kind' AND (CASE WHEN entry->>'kind'='PAYMENT' THEN value->'entry'->>'out_trade_no_hex'=entry->>'out_trade_no_hex' ELSE value->'entry'->>'out_refund_no_hex'=entry->>'out_refund_no_hex' END);
   IF NOT FOUND THEN CONTINUE;END IF;
   system_identity:=proof->'entry';
   has_this:=proof->'payment_proof'->>'state'='VALID' AND proof->'payment_proof'->>'environment'=p_environment AND system_identity->>'appid_hex'=encode(convert_to(p_evidence->>'appid','UTF8'),'hex') AND system_identity->>'mchid_hex'=encode(convert_to(p_evidence->>'merchant_id','UTF8'),'hex');
   IF entry->>'kind'='REFUND' THEN has_this:=has_this AND proof->'refund_proof'->>'state'='VALID' AND proof->'refund_proof'->>'environment'=p_environment;END IF;
   IF convert_from(decode(system_identity->>'out_trade_no_hex','hex'),'UTF8') ~ (CASE WHEN p_environment='uat' THEN '^OP1P[0-9a-f]{28}$' ELSE '^OU1P[0-9a-f]{28}$' END) OR convert_from(decode(system_identity->>'out_refund_no_hex','hex'),'UTF8') ~ (CASE WHEN p_environment='uat' THEN '^OP1R[0-9a-f]{28}$' ELSE '^OU1R[0-9a-f]{28}$' END) THEN has_this:=false;END IF;
  END IF;
  IF NOT has_this THEN CONTINUE;END IF;
  -- Only the original target field is consumed. Raw bytea deliberately keeps invalid UTF8 and NUL.
  IF entry->>'kind'='PAYMENT' THEN
   IF (entry->>'out_trade_no_hex') !~ '^([0-9a-f]{2})*$' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   SELECT id INTO target_id FROM public.prepayments WHERE out_trade_no=decode(entry->>'out_trade_no_hex','hex');
  ELSE
   IF (entry->>'out_refund_no_hex') !~ '^([0-9a-f]{2})*$' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
   SELECT id INTO target_id FROM public.refunds WHERE out_refund_no=decode(entry->>'out_refund_no_hex','hex');
  END IF;
  IF NOT FOUND THEN CONTINUE;END IF;
 IF target_id IS NULL OR target_id NOT BETWEEN 0 AND 18446744073709551615 OR trunc(target_id)<>target_id THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
  IF entry->>'kind'='PAYMENT' THEN payment_ids:=array_append(payment_ids,target_id);ELSE refund_ids:=array_append(refund_ids,target_id);END IF;
 END LOOP;
 -- Original map deduplication and sorted unsigned numeric id order, payments before refunds.
 FOR target_id IN SELECT DISTINCT value FROM unnest(payment_ids) AS ids(value) ORDER BY value LOOP
  UPDATE public.prepayments SET materialization_state='PENDING_MANUAL',pending_reason_code='BILL_MISMATCH',materialized_at=NULL,record_version=record_version+1,updated_at=clock_timestamp() WHERE id=target_id AND materialization_state IN ('AWAITING_PAYMENT','READY','PENDING_MANUAL');
 END LOOP;
 FOR target_id IN SELECT DISTINCT value FROM unnest(refund_ids) AS ids(value) ORDER BY value LOOP
  UPDATE public.refunds SET materialization_state='PENDING_MANUAL',pending_reason_code='BILL_MISMATCH',materialized_at=NULL,record_version=record_version+1,updated_at=clock_timestamp() WHERE id=target_id AND materialization_state<>'APPLIED';
 END LOOP;
 -- All failures after a write must raise into this block's exception handler, rolling its subtransaction back.
 IF p_matched IS NULL OR p_matched NOT BETWEEN 0 AND 18446744073709551615 OR trunc(p_matched)<>p_matched THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_BILLING_UNAVAILABLE';END IF;
 evidence:=p_evidence;
 audit_result:='SUCCEEDED';reason:='BILL_MATCHED';
 IF jsonb_array_length(p_provider_only)>0 OR jsonb_array_length(p_system_only)>0 THEN audit_result:='REJECTED';reason:='BILL_MISMATCH';END IF;
 IF unknown THEN audit_result:='REJECTED';reason:='BILL_OWNERSHIP_UNKNOWN';END IF;
 -- Approved host-clock change: sample at the original audit INSERT consumption point, after every pending UPDATE.
 audit_at:=clock_timestamp();
 INSERT INTO public.action_audits(entry_kind,actor_kind,actor_scope_hash,actor_user_id,actor_account_id,action,target_type,target_id,target_key_hash,operation_key_hash,result,reason_code,after_state_json,occurred_at)
 VALUES('SYSTEM_EVIDENCE','PROVIDER',sha256(convert_to('PROVIDER:BILLING','UTF8')),NULL,NULL,'billing.reconcile','BILL',NULL,intrinsic,NULL,audit_result,reason,evidence,audit_at);
 RETURN jsonb_build_object('outcome','RECONCILED');
 EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END;
END
$order_rpc$;
REVOKE ALL ON FUNCTION public.order_billing_reconcile_v2(text,text,numeric,jsonb,jsonb,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.order_billing_reconcile_v2(text,text,numeric,jsonb,jsonb,text,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.order_billing_reconcile_v1(text,text,numeric,jsonb,jsonb) FROM authenticated;
